def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 70
    WATER_REQ = 13

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0

    alive = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, DAILY_SALARY * 0.9)
        return min(budget, DAILY_SALARY * 0.35)

    prev_bids = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 0) <= 2 or opp.get('no_water_days', 0) >= 2:
            desperate_count += 1
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)

    highest_prev = max(prev_bids) if prev_bids else None
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else None

    scarcity = (25.0 - supply) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    if hp <= 1 or no_water_days >= 2:
        base = DAILY_SALARY * (0.92 + 0.05 * scarcity)
    elif hp <= 2 or no_water_days >= 1:
        base = DAILY_SALARY * (0.74 + 0.10 * scarcity)
    else:
        base = DAILY_SALARY * (0.42 + 0.18 * scarcity)

    if desperate_count > 0:
        base += 4 + 2 * desperate_count
    if rich_count >= max(1, len(alive) // 2):
        base += 3

    if highest_prev is not None:
        if hp > 3 and no_water_days == 0 and highest_prev >= DAILY_SALARY * 0.9:
            bid = DAILY_SALARY * (0.28 + 0.10 * scarcity)
        else:
            target = highest_prev + 1.5
            if avg_prev is not None:
                target = max(target, avg_prev + 1.0)
            bid = max(base, target)
    else:
        bid = base

    if day >= 8 and budget < DAILY_SALARY * (11 - day):
        bid = min(bid, DAILY_SALARY * 0.6)

    if hp > 3 and no_water_days == 0 and supply >= 22:
        bid = min(bid, DAILY_SALARY * 0.45)

    if hp <= 2:
        bid = max(bid, DAILY_SALARY * 0.8)

    if bid < 0:
        bid = 0
    if bid > budget:
        bid = budget
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    # If no opponents are alive, bid conservatively.
    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Read only yesterday's immediate behavior.
    prev_bids = []
    for _, o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Baseline bid fraction
    # We want to be competitive but not drain budget.
    # Also increase slightly when our HP is low.
    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    # Estimate scarcity: lower supply -> higher pressure.
    # supply is float; map to [0,1] using explicit int indices not needed here.
    scarcity = 0.0
    try:
        scarcity = (MAX_SUPPLY - float(supply)) / float(MAX_SUPPLY - MIN_SUPPLY)
    except Exception:
        scarcity = 0.5
    if scarcity < 0.0:
        scarcity = 0.0
    if scarcity > 1.0:
        scarcity = 1.0

    base = DAILY_SALARY * (0.45 + 0.25 * scarcity)  # ~40-70
    if hp <= 2:
        base = DAILY_SALARY * 0.85
    elif hp <= 3:
        base = DAILY_SALARY * 0.70

    # React to opponent yesterday bids if available.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If they were bidding aggressively, match their pressure.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if hp > 3:
                bid = DAILY_SALARY * 0.35
            else:
                bid = DAILY_SALARY * 0.95
        # If they were moderate, slightly overbid to secure.
        elif highest_prev_bid >= DAILY_SALARY * 0.55:
            bid = max(base, highest_prev_bid + 1.0)
        else:
            # If they were low, keep base but nudge a bit upward.
            bid = max(base, highest_prev_bid + 0.5)
    else:
        # No trace info: use baseline.
        bid = base

    # Budget and day-end caution: preserve budget for remaining days.
    # Episode days fixed at 10 in meta-round; use remaining days heuristic.
    try:
        remaining_days = int(10 - int(day))
    except Exception:
        remaining_days = 5
    if remaining_days <= 0:
        remaining_days = 1

    # Don't spend more than an even-share of budget across remaining days.
    max_affordable = float(budget) / float(remaining_days)
    bid = min(float(bid), max_affordable)

    # Ensure non-negative and at least minimal competitive amount.
    if bid < 0:
        bid = 0

    return min(bid, float(budget))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140

    MIN_BID_FACTOR = 0.1 
    LOW_HP_THRESHOLD = 2 
    HEALTHY_HP_THRESHOLD = 3 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)
    num_total_bidders = num_alive_opponents + 1 

    # --- Step 1: Handle critical survival situations ---
    if my_status['hp'] <= LOW_HP_THRESHOLD or my_status['no_water_days'] > 0:
        return min(my_status['budget'], DAILY_SALARY * 0.95) 

    # --- Step 2: Handle no competition ---
    if num_total_bidders == 1:
        return min(my_status['budget'], DAILY_SALARY * MIN_BID_FACTOR)

    # --- Step 3: Calculate a base bid considering current supply and competition ---
    supply = day_context['supply']

    max_agents_to_satisfy = int(supply // WATER_REQ)

    base_bid = DAILY_SALARY * 0.5 

    if num_total_bidders > max_agents_to_satisfy:
        pressure_factor = num_total_bidders / max_agents_to_satisfy if max_agents_to_satisfy > 0 else num_total_bidders
        base_bid *= min(1.0 + (pressure_factor - 1.0) * 0.4, 1.5) 
    elif supply >= num_total_bidders * WATER_REQ:
        base_bid *= 0.7 
    else:
        base_bid *= 0.9 

    base_bid = max(DAILY_SALARY * MIN_BID_FACTOR, min(base_bid, DAILY_SALARY * 0.9))

    # --- Step 4: React to yesterday's opponent bids ---
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    final_bid = base_bid 

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > HEALTHY_HP_THRESHOLD: 
                final_bid = DAILY_SALARY * 0.3
            else:
                final_bid = DAILY_SALARY * 0.95
        else:
            final_bid = max(base_bid, highest_prev_bid + (DAILY_SALARY * 0.02)) 

    # --- Step 5: Final bid adjustment and budget constraint ---
    final_bid = max(DAILY_SALARY * MIN_BID_FACTOR, final_bid) 
    return min(my_status['budget'], final_bid)
